-- Forward-only, like every migration here (persistence.md): there is no down
-- step; dropping the four tables undoes it. Identity's seeded descriptions of
-- live.speak and live.moderate ("… in live sessions one hosts", 0002) are
-- deliberately NOT changed here: rewording catalogue text is not additive, and
-- is proposed separately as an identity-data migration (P6 audit §17.12).

CREATE TABLE "live_moderation_actions" (
	"id" text PRIMARY KEY NOT NULL,
	"session_id" text NOT NULL,
	"actor_user_id" text,
	"target_user_id" text,
	"type" text NOT NULL,
	"at" timestamp with time zone NOT NULL,
	"reason_code" text,
	CONSTRAINT "live_moderation_actions_type_valid" CHECK ("live_moderation_actions"."type" in ('start_session', 'end_session', 'grant_speaker', 'decline_speaker', 'revoke_speaker', 'grant_presenter', 'revoke_presenter', 'reset_media', 'mute_participant', 'remove_participant')),
	CONSTRAINT "live_moderation_actions_reason_code_shape" CHECK ("live_moderation_actions"."reason_code" is null or "live_moderation_actions"."reason_code" ~ '^[a-z][a-z0-9_.]{0,63}$')
);
