CREATE TABLE "live_presenter_grants" (
	"id" text PRIMARY KEY NOT NULL,
	"session_id" text NOT NULL,
	"user_id" text NOT NULL,
	"granted_by" text NOT NULL,
	"granted_at" timestamp with time zone NOT NULL,
	"ended_at" timestamp with time zone,
	"ended_by" text,
	"end_reason" text,
	CONSTRAINT "live_presenter_grants_end_reason_valid" CHECK ("live_presenter_grants"."end_reason" in ('stopped', 'revoked', 'session_ended', 'ineligible')),
	CONSTRAINT "live_presenter_grants_end_consistent" CHECK (("live_presenter_grants"."ended_at" is null) = ("live_presenter_grants"."end_reason" is null)),
	CONSTRAINT "live_presenter_grants_ended_by_needs_end" CHECK ("live_presenter_grants"."ended_by" is null or "live_presenter_grants"."ended_at" is not null)
);
--> statement-breakpoint
CREATE TABLE "live_sessions" (
	"id" text PRIMARY KEY NOT NULL,
	"community_id" text NOT NULL,
	"host_user_id" text NOT NULL,
	"state" text NOT NULL,
	"state_version" bigint NOT NULL,
	"started_at" timestamp with time zone NOT NULL,
	"ended_at" timestamp with time zone,
	"ended_by" text,
	"end_reason" text,
	"participant_cap" bigint NOT NULL,
	"moderator_reserve" bigint NOT NULL,
	"media_room_epoch" integer DEFAULT 0 NOT NULL,
	"empty_since" timestamp with time zone,
	"enforcement_violations" integer DEFAULT 0 NOT NULL,
	"last_violation_at" timestamp with time zone,
	CONSTRAINT "live_sessions_state_valid" CHECK ("live_sessions"."state" in ('live', 'ended')),
	CONSTRAINT "live_sessions_end_reason_valid" CHECK ("live_sessions"."end_reason" in ('moderator', 'idle', 'community_closed')),
	CONSTRAINT "live_sessions_state_version_positive" CHECK ("live_sessions"."state_version" >= 1),
	CONSTRAINT "live_sessions_participant_cap_positive" CHECK ("live_sessions"."participant_cap" > 0),
	CONSTRAINT "live_sessions_moderator_reserve_nonnegative" CHECK ("live_sessions"."moderator_reserve" >= 0),
	CONSTRAINT "live_sessions_media_room_epoch_nonnegative" CHECK ("live_sessions"."media_room_epoch" >= 0),
	CONSTRAINT "live_sessions_enforcement_violations_nonnegative" CHECK ("live_sessions"."enforcement_violations" >= 0),
	CONSTRAINT "live_sessions_ended_at_consistent" CHECK (("live_sessions"."state" = 'live') = ("live_sessions"."ended_at" is null)),
	CONSTRAINT "live_sessions_end_reason_consistent" CHECK (("live_sessions"."state" = 'live') = ("live_sessions"."end_reason" is null)),
	CONSTRAINT "live_sessions_moderator_end_named" CHECK ("live_sessions"."end_reason" is distinct from 'moderator' or "live_sessions"."ended_by" is not null),
